  transform: translateY(-3px);
  box-shadow: 0 0 20px color-mix(in srgb, var(--green) 20%, transparent);
}

.snake-app-icon {
  width: 72px;
  height: 72px;
  background: var(--ink);
  border: 1px solid var(--green);
  display: grid;
  place-items: center;
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--green) 15%, transparent);
  position: relative;
  pointer-events: none;
}

.snake-icon-canvas {
  width: 56px;
  height: 56px;
  display: block;
  pointer-events: none;
}

.snake-icon-label {
  font-family: var(--display);
  font-size: 16px;
  color: var(--paper);
  margin: 0;
  pointer-events: none;
}

.snake-icon-sub {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--green);
  letter-spacing: 0.05em;
  pointer-events: none;
}

